const p = $json.body ?? $json;
const type = String(p.type ?? p.event_type ?? '');
const esc = (v) => String(v ?? '').replace(/[&<>\"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const manager = String(p.manager_email ?? p.to_email ?? '');
const customer = String(p.to_email ?? '');
const ref = esc(p.event_id ?? 'not provided');
let to = ''; let title = ''; let summary = ''; let details = '';
switch (type) {
  case 'integration.test': to = manager; title = 'Automation connection test'; summary = 'INKORA successfully reached the n8n event workflow.'; details = 'No business data was changed.'; break;
  case 'order.created': to = customer || manager; title = 'Order received'; summary = 'Your order has been received by the shop.'; details = `Order ${esc(p.order_id)} · Status ${esc(p.status)} · Total EGP ${esc(p.total)}`; break;
  case 'order.ready': to = customer || manager; title = 'Your order is ready'; summary = 'Production has completed its quality check.'; details = `Order ${esc(p.order_id)} is ready for pickup or delivery coordination.`; break;
  case 'order.status_changed': to = customer || manager; title = 'Order status updated'; summary = `Order ${esc(p.order_id)} changed from ${esc(p.previous_status)} to ${esc(p.status)}.`; details = `Order total: EGP ${esc(p.total)}.`; break;
  case 'production.status_changed': if (!['ready','cancelled'].includes(String(p.status))) { to = manager; title = 'Production stage updated'; summary = `Job ${esc(p.production_job_id)} moved to ${esc(p.status)}.`; details = `Order ${esc(p.order_id)} · Previous stage ${esc(p.previous_status)}.`; } break;
  case 'inventory.low_stock': to = manager; title = `Low stock: ${esc(p.name)}`; summary = 'Available material reached or fell below its reorder point.'; details = `Available ${esc(p.available_stock)} ${esc(p.unit)} · Reorder point ${esc(p.reorder_point)} · Suggested order ${esc(p.reorder_quantity)}.`; break;
  case 'inventory.restocked': to = manager; title = `Material restocked: ${esc(p.name)}`; summary = 'Available stock is back above its configured reorder point.'; details = `Available ${esc(p.available_stock)} ${esc(p.unit)} · Reorder point ${esc(p.reorder_point)}.`; break;
  case 'product.out_of_stock': to = manager; title = `Out of stock: ${esc(p.product_name)}`; summary = 'A product variant has no remaining sellable quantity.'; details = `Product ${esc(p.product_name)} · SKU ${esc(p.variant_sku)} · Check availability before promoting it.`; break;
  case 'product.restocked': to = manager; title = `Product restocked: ${esc(p.product_name)}`; summary = 'A product variant received additional available quantity.'; details = `Product ${esc(p.product_name)} · SKU ${esc(p.variant_sku)} · Available ${esc(p.available_quantity)}.`; break;
  case 'product.created': to = manager; title = 'Product added'; summary = `${esc(p.name)} was added to the catalog.`; details = `SKU ${esc(p.sku)} · Category ${esc(p.category)}.`; break;
  case 'product.updated': to = manager; title = 'Product updated'; summary = `${esc(p.name)} was updated in the catalog.`; details = `SKU ${esc(p.sku)} · Category ${esc(p.category)} · Active ${esc(p.active)}.`; break;
  case 'product.options.updated': to = manager; title = 'Product options updated'; summary = 'A manager changed configurable product options or approved surcharges.'; details = `Product ${esc(p.product_id)} · Option groups ${esc(p.option_group_count)}.`; break;
  case 'storefront.published': to = manager; title = 'Storefront update published'; summary = `Approved storefront version ${esc(p.version)} is live.`; details = 'The customer store is serving the published configuration.'; break;
  case 'marketing.approved': to = manager; title = 'Marketing draft approved'; summary = 'A marketing asset was approved in INKORA.'; details = `Asset ${esc(p.asset_id)} · Platform ${esc(p.platform)}.`; break;
}
const send = Boolean(to && title);
const html = `<div style="margin:0;background:#f3f4f6;padding:32px 12px;font-family:Arial,sans-serif;color:#171717"><div style="max-width:560px;margin:auto;background:#fff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden"><div style="background:#111827;padding:20px 24px;color:#fff;font-size:18px;font-weight:700;letter-spacing:1px">INKORA <span style="font-size:12px;font-weight:400;color:#cbd5e1">STORE OPERATIONS</span></div><div style="padding:28px 24px"><p style="margin:0 0 8px;color:#2563eb;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px">Business update</p><h1 style="font-size:22px;margin:0 0 14px">${title}</h1><p style="font-size:15px;line-height:1.6;color:#374151;margin:0 0 18px">${summary}</p><div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:16px;font-size:14px;line-height:1.6">${details}</div><p style="font-size:11px;color:#6b7280;margin:22px 0 0">Event reference: ${ref}</p></div><div style="border-top:1px solid #e5e7eb;padding:14px 24px;color:#6b7280;font-size:11px">Automated business notification from INKORA</div></div></div>`;
return [{json: {should_send: send, to_email: to, subject: `INKORA · ${title || 'Event ignored'}`, html, event_id: ref, event_type: type}}];
